// 📁 src/app/core/models/property.interface.ts
// 🏠 INTERFACES CORREGIDAS CON COMPATIBILIDAD

export type PropertyType = 'habitacion' | 'suite' | 'apartamento' | 'studio' | 'casa' | 'penthouse';

// 🏠 Solo una zona: la casa principal (pero mantenemos compatibilidad)
export type ZoneType = 'casa-norte-armenia' | 'norte-centro' | 'la-secreta' | 'bosques-pinares' | 'ciudadela-del-cafe' | 'villa-liliana';

export type AmenityType = 
  | 'wifi' 
  | 'parking'
  | 'breakfast' 
  | 'kitchen'
  | 'ac'
  | 'tv'
  | 'washing-machine'
  | 'security'
  | 'elevator'
  | 'balcony';

export type ServiceType = 
  | 'cleaning'
  | 'transport' 
  | 'luggage-storage'
  | 'concierge'
  | 'tour-info'
  | 'late-checkin';

export interface Property {
  id: string;
  title: string;
  location: string;
  zone: ZoneType; // Mantiene compatibilidad
  address?: string;
  description: string;
  
  // 💰 Precios
  pricePerNight: number;
  pricePerWeek?: number;
  pricePerMonth?: number;
  currency: 'COP';
  
  // ⭐ Calificaciones
  rating: number;
  reviewsCount: number;
  
  // 🖼️ Imágenes
  image: string;
  images?: string[];
  
  // 🏠 Características físicas
  propertyType: PropertyType;
  bedrooms: number;
  bathrooms: number;
  maxGuests: number;
  area?: number;
  floor?: number;
  
  // 🎯 Características específicas
  features: string[];
  amenities: AmenityType[];
  services: ServiceType[];
  
  // 👤 Información del anfitrión
  hostName: string;
  hostPhoto?: string;
  hostWhatsapp?: string;
  responseTime?: string;
  
  // 📍 Ubicación y acceso
  nearbyPlaces: string[];
  transportAccess: string[];
  
  // ⏰ Políticas
  checkInTime: string;
  checkOutTime: string;
  minimumStay?: number;
  cancellationPolicy?: 'flexible' | 'moderada' | 'estricta';
  
  // 🏷️ Estados
  isFavorite: boolean;
  isVerified: boolean;
  isInstantBook: boolean;
  isAvailable: boolean;
  
  // 📅 Fechas
  createdAt: string;
  updatedAt: string;
}

// 🛏️ INTERFAZ ESPECÍFICA PARA HABITACIÓN
export interface Room extends Property {
  roomNumber?: string;
  roomFeatures: string[];
  isOccupied?: boolean;
  lastCleaned?: string;
}

// 🎛️ CONFIGURACIÓN DE TARJETAS
export interface PropertyCardConfig {
  displayMode: 'compact' | 'detailed' | 'horizontal';
  showFavoriteButton: boolean;
  showPricing: boolean;
  showFeatures: boolean;
  showContact: boolean;
  showAvailability: boolean;
}

// 🔍 FILTROS (CON COMPATIBILIDAD)
export interface PropertyFilters {
  propertyTypes: PropertyType[];
  amenities: AmenityType[];
  services: ServiceType[];
  minPrice: number;
  maxPrice: number;
  minRating: number;
  maxGuests: number;
  instantBook: boolean;
  verified: boolean;
  available: boolean;
}

