export const calculateNights = (checkIn: string, checkOut: string): number => {
  if (!checkIn || !checkOut) return 0;
  
  const checkInDate = new Date(checkIn);
  const checkOutDate = new Date(checkOut);
  const timeDiff = checkOutDate.getTime() - checkInDate.getTime();
  return Math.ceil(timeDiff / (1000 * 3600 * 24));
};

export const getStayCategory = (nights: number): keyof StayDurationFilters => {
  if (nights >= 30) return 'monthly';
  if (nights >= 7) return 'weekly';
  return 'shortTerm';
};

export const isWeekend = (date: string): boolean => {
  const day = new Date(date).getDay();
  return day === 0 || day === 6; // Domingo o Sábado
};

export const getSeasonality = (date: string): 'alta' | 'media' | 'baja' => {
  const month = new Date(date).getMonth() + 1;
  
  // Temporada alta: Diciembre, Enero, Semana Santa, Junio-Julio
  if ([12, 1, 6, 7].includes(month)) return 'alta';
  
  // Temporada media: Marzo, Abril, Noviembre
  if ([3, 4, 11].includes(month)) return 'media';
  
  return 'baja';
};
